      'Synchronization\\DAQ_Route synchronization signals.vi',
      inputs: {
        'DAQmx Task In': locals.signalGenTask,
        'Routing paths.[0].Signal': 0,
        'Routing paths.[0].Output Terminal': '/Simulated_DAQ/PFI0',
