      'Time Domain Measurement\\DAQ_TDV Meas Configure and Measure.vi',
      inputs: {
        'Execution Settings.Execution option': 1,
        'DAQmx Task In': locals.timeDomainMeasTask,
        'Timing and Trigger Settings.Timing Settings.Sample Clock Source': '/Simulated_DAQ/PFI0',
        'Timing and Trigger Settings.Timing Settings.Sample Rate(Hz)': 10000,
        'Timing and Trigger Settings.Trigger Settings.Trigger Type': 1,
        'Timing and Trigger Settings.Trigger Settings.Digital Start Trigger Source': '/Simulated_DAQ/PFI1',
        'Timing and Trigger Settings.Trigger Settings.Digital Start Trigger Edge': 10280,
      },
    ); // Time Domain Measurement - Configure TP
    //
    // Generate Sine waveform from analog module
    final outputs3 = await ts.callVi(
      'Signal Voltage Generation\\DAQ_SV Gen Configure and Generate.vi',
      inputs: {
        'DAQmx Task In': locals.signalGenTask,
        'Signal Generation Settings.Generation Time (s)': 0.1,
        'Signal Generation Settings.Single Tone Settings.Frequency (Hz)': 100,
        'Signal Generation Settings.Single Tone Settings.Amplitude (V)': 1,
