    ); // Signal Voltage Generation - Close
    await ts.callVi(
      'Time Domain Measurement\\DAQ_TDV Meas Close.vi',
      inputs: {'DAQmx Task In': locals.timeDomainMeasTask},
    ); // Time Domain Measurement - Close
  }
}

